import random, time

def backoff_delay(attempt: int, base: float = 1.0, cap: float = 30.0) -> float:
    # exponential growth, capped, with full jitter
    raw = min(cap, base * (2 ** attempt))
    return random.uniform(0, raw)   # full jitter avoids synchronized retries

for attempt in range(5):
    try:
        result = call_model(payload)
        break
    except (requests.Timeout, requests.ConnectionError):
        time.sleep(backoff_delay(attempt))   # 0-1s, 0-2s, 0-4s, ...
else:
    raise RuntimeError("model call failed after retries")

def sleep_for_rate_limit(resp, attempt: int) -> None:
    retry_after = resp.headers.get("Retry-After")
    if retry_after is not None:
        # provider told us exactly how long to wait -- obey it
        time.sleep(float(retry_after))
    else:
        # no header: fall back to our own backoff
        time.sleep(backoff_delay(attempt))

