import time

class CircuitBreaker:
    def __init__(self, threshold=5, cooldown=30.0):
        self.threshold, self.cooldown = threshold, cooldown
        self.failures, self.opened_at = 0, None
    def allow(self) -> bool:
        if self.opened_at is None:
            return True                      # closed: calls flow
        if time.time() - self.opened_at > self.cooldown:
            return True                      # half-open: allow one trial
        return False                         # open: fail fast
    def record(self, ok: bool) -> None:
        if ok:
            self.failures, self.opened_at = 0, None   # reset on success
        else:
            self.failures += 1
            if self.failures >= self.threshold:
                self.opened_at = time.time()          # trip the breaker

class ResilientClient:
    def __init__(self, breaker: CircuitBreaker, max_retries=4):
        self.breaker, self.max_retries = breaker, max_retries
    def call(self, payload: dict) -> dict:
        if not self.breaker.allow():
            raise RuntimeError("circuit open: dependency unavailable")
        for attempt in range(self.max_retries):
            try:
                result = call_model(payload)   # already has a timeout
                self.breaker.record(ok=True)
                return result
            except requests.HTTPError as e:
                if e.response.status_code == 429:
                    sleep_for_rate_limit(e.response, attempt)
                    continue
                raise
            except (requests.Timeout, requests.ConnectionError):
                self.breaker.record(ok=False)
                time.sleep(backoff_delay(attempt))
        raise RuntimeError("exhausted retries")

