class Clock:
    def __init__(self): self.now = 0.0
    def tick(self, s): self.now += s

class CircuitBreaker:
    def __init__(self, clock, threshold=3, cooldown=10.0):
        self.clock, self.threshold, self.cooldown = clock, threshold, cooldown
        self.failures, self.opened_at = 0, None
    def allow(self):
        if self.opened_at is None:
            return True
        if self.clock.now - self.opened_at > self.cooldown:
            return True                      # half-open trial
        return False                         # open: fail fast
    def record(self, ok):
        if ok:
            self.failures, self.opened_at = 0, None
        else:
            self.failures += 1
            if self.failures >= self.threshold:
                self.opened_at = self.clock.now

clock = Clock()
cb = CircuitBreaker(clock)
for _ in range(3):
    cb.record(ok=False)                      # three failures trip it
print("after 3 fails, allow?", cb.allow())
clock.tick(5)
print("5s later (still cooling), allow?", cb.allow())
clock.tick(6)
print("11s later (cooldown passed), allow?", cb.allow())
cb.record(ok=True)                            # trial succeeds -> closed
print("after successful trial, allow?", cb.allow())

