class TransientError(Exception):
    pass

class RateLimited(Exception):
    def __init__(self, retry_after: float):
        self.retry_after = retry_after

class FatalError(Exception):
    pass

def resilient_call(fn, sleep, backoff_delay, max_retries=4):
    for attempt in range(max_retries):
        try:
            return fn()                       # success path
        except FatalError:
            raise                             # never retry a fatal error
        except RateLimited as e:
            sleep(e.retry_after)              # obey the provider's wait
        except TransientError:
            sleep(backoff_delay(attempt))     # exponential backoff + jitter
    raise RuntimeError("exhausted retries")

