log = []
def sleep(s): log.append(("sleep", round(s, 2)))
def backoff_delay(attempt): return float(attempt)   # deterministic

# 1) succeeds after two transient failures
state = {"n": 0}
def flaky():
    state["n"] += 1
    if state["n"] < 3:
        raise TransientError()
    return "ok"
assert resilient_call(flaky, sleep, backoff_delay) == "ok"
assert log == [("sleep", 0.0), ("sleep", 1.0)], log

# 2) rate limit uses retry_after, not backoff
log.clear(); state["n"] = 0
def throttled():
    state["n"] += 1
    if state["n"] == 1:
        raise RateLimited(retry_after=7.0)
    return "done"
assert resilient_call(throttled, sleep, backoff_delay) == "done"
assert log == [("sleep", 7.0)], log

# 3) fatal error is never retried
def fatal():
    raise FatalError()
try:
    resilient_call(fatal, sleep, backoff_delay)
    raise AssertionError("should have raised FatalError")
except FatalError:
    pass

# 4) exhausting retries raises RuntimeError
def always_transient():
    raise TransientError()
try:
    resilient_call(always_transient, sleep, backoff_delay, max_retries=2)
    raise AssertionError("should have exhausted")
except RuntimeError as e:
    assert str(e) == "exhausted retries"
print("all tests passed")

