import functools
import random
import time

def with_retries(exceptions, max_retries=4, base=1.0, cap=30.0,
                 sleep=time.sleep, rng=random.random):
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            last = None
            for attempt in range(max_retries):
                try:
                    return fn(*args, **kwargs)
                except exceptions as e:
                    last = e
                    ceiling = min(cap, base * (2 ** attempt))
                    sleep(rng() * ceiling)   # full jitter in [0, ceiling]
            raise last                       # all attempts failed
        return wrapper
    return decorator

if __name__ == "__main__":
    calls = {"n": 0}

    @with_retries((TimeoutError,), max_retries=5, sleep=lambda s: None)
    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise TimeoutError("transient")
        return "ok"

    print(flaky(), "after", calls["n"], "calls")
